function CancelShop1DragFx() {
    if (!shop1DragFx.active) {
        return;
    }
    StopShop1DragFx();
    if (GameEvents) {
        GameEvents.SendCustomGameEventToServer("shop1_drag_fx_cancel", {});
    }
}

function StartShop1DragFx(sourceEnt, iconPath) {
    if (!sourceEnt || sourceEnt < 0) {
        Shop1Log("drag_start_invalid", { sourceEnt: sourceEnt, icon: iconPath || "" }, true);
        return;
    }
    if (shop1DragFx.active && shop1DragFx.sourceEnt === sourceEnt && shop1DragFx.iconPath === iconPath) {
        return;
    }
    if (SHOP1_DRAG_DEBUG) {
        $.Msg("[Shop1DragFx] Start", "sourceEnt=", sourceEnt, "icon=", iconPath);
    }
    StopShop1DragFx();
    shop1DragFx.active = true;
    shop1DragStartTime = Game.GetGameTime();
    shop1DragFx.sourceEnt = sourceEnt;
    shop1DragFx.iconPath = iconPath;
    if (iconPath) {
        PreloadShop1Icon(iconPath, "drag_start");
    }
    var cfg = GameUI.CustomUIConfig();
    shop1DragFx.proxyEnt = cfg && cfg.shop1_dummy_proxy_ent !== undefined ? cfg.shop1_dummy_proxy_ent : -1;
    shop1DragFx.lockEnt = (shop1DragFx.proxyEnt && shop1DragFx.proxyEnt > 0) ? shop1DragFx.proxyEnt : sourceEnt;
    if (!shop1DragFx.container) {
        shop1DragFx.container = $("#Shop1DragLayer");
        if (!shop1DragFx.container) {
            var parent = GetHudPanelSafe();
            shop1DragFx.hud = parent;
            shop1DragFx.container = $.CreatePanel("Panel", parent, "Shop1DragLayer");
            shop1DragFx.container.style.width = "100%";
            shop1DragFx.container.style.height = "100%";
            shop1DragFx.container.style.flowChildren = "none";
            shop1DragFx.container.style.zIndex = "1000";
            shop1DragFx.container.hittest = false;
        }
    } else if (!shop1DragFx.hud && typeof GetDotaHud === "function") {
        shop1DragFx.hud = GetHudPanelSafe();
    }
    // icon display moved to world panel, particle handled on server
    if (GameEvents) {
        var cursorPos = GameUI.GetCursorPosition();
        if (cursorPos && cursorPos.length >= 2) {
            var world = ScreenToWorldAtZ(cursorPos[0], cursorPos[1], z_height);
            if (!world && GameUI.GetScreenWorldPosition) {
                world = GameUI.GetScreenWorldPosition(cursorPos[0], cursorPos[1]);
            }
            if (world) {
                Shop1Log("drag_start_send", {
                    sourceEnt: sourceEnt,
                    icon: iconPath,
                    x: world[0],
                    y: world[1],
                    z: world[2]
                }, true);
                if (SHOP1_DRAG_DEBUG) {
                    $.Msg("[Shop1DragFx] StartPos", "x=", world[0], "y=", world[1], "z=", world[2]);
                }
                GameEvents.SendCustomGameEventToServer("shop1_drag_fx_start", {
                    x: world[0],
                    y: world[1],
                    z: world[2],
                    icon: iconPath || "",
                    source_ent: sourceEnt,
                    proxy_ent: (shop1DragFx.proxyEnt && shop1DragFx.proxyEnt > 0) ? shop1DragFx.proxyEnt : -1
                });
            } else {
                Shop1Log("drag_start_no_world", { cursor: cursorPos, z: z_height }, true);
            }
        } else {
            Shop1Log("drag_start_no_cursor", {}, true);
        }
    }
    UpdateShop1DragFx();
    StartReleaseWatch();
}

function StartReleaseWatch() {
    if (shop1ReleaseWatchActive) {
        return;
    }
    shop1ReleaseWatchActive = true;
    (function WatchRelease() {
        if (!shop1DragFx.active) {
            shop1ReleaseWatchActive = false;
            return;
        }
        if (shop1ReleasePending) {
            $.Schedule(0.03, WatchRelease);
            return;
        }
        if (GameUI.IsMouseDown && GameUI.IsMouseDown(0) === false) {
            shop1ReleasePending = true;
            shop1LeftDown = false;
            shop1SwallowPressed = false;
            Shop1Log("left_release_watch", { dragActive: shop1DragFx.active }, true);
            SendLeftRelease();
            StopShop1DragFx();
            $.Schedule(0.2, function () {
                shop1ReleasePending = false;
            });
            shop1ReleaseWatchActive = false;
            return;
        }
        $.Schedule(0.03, WatchRelease);
    })();
}

function UpdateShop1DragFxState() {
    if (!shop1DragFx.active) {
        return;
    }
    if (shop1ReleasePending) {
        return;
    }
    if (!shop1LeftDown) {
        shop1SwallowPressed = false;
        Shop1Log("drag_state_cancel_left_up", {}, true);
        CancelShop1DragFx();
        return;
    }
    var selected = Players.GetSelectedEntities(Players.GetLocalPlayer());
    var ent = selected && selected.length > 0 ? selected[0] : -1;
    var sourceEnt = shop1DragFx.sourceEnt || GetShop1DragSourceEnt();
    if (!ent || ent < 0 || !sourceEnt || sourceEnt < 0) {
        Shop1Log("drag_state_cancel_invalid_sel", { ent: ent, sourceEnt: sourceEnt }, true);
        CancelShop1DragFx();
        return;
    }
    var cfg = GameUI.CustomUIConfig();
    var proxyEnt = shop1DragFx.proxyEnt !== undefined ? shop1DragFx.proxyEnt :
        (cfg && cfg.shop1_dummy_proxy_ent !== undefined ? cfg.shop1_dummy_proxy_ent : -1);
    if (ent !== sourceEnt && ent !== proxyEnt) {
        var portrait = Players.GetLocalPlayerPortraitUnit && Players.GetLocalPlayerPortraitUnit();
        if (cfg && cfg.selection_is_position || portrait === -1) {
            Shop1Log("drag_state_cancel_position", { ent: ent, sourceEnt: sourceEnt }, true);
            CancelShop1DragFx();
            return;
        }
        if (shop1DragFx.lockEnt && shop1DragFx.lockEnt > 0) {
            skip = true;
            GameUI.SelectUnit(shop1DragFx.lockEnt, false);
            return;
        }
        Shop1Log("drag_state_cancel_other", { ent: ent, sourceEnt: sourceEnt, proxyEnt: proxyEnt }, true);
        CancelShop1DragFx();
        return;
    }
    // do not stop drag fx if hero icon hasn't arrived yet
}

function UpdateShop1DragFx() {
    if (!shop1DragFx.active) {
        return;
    }
    var cursor = GameUI.GetCursorPosition();
    if (cursor && cursor.length >= 2) {
        var world = ScreenToWorldAtZ(cursor[0], cursor[1], z_height);
        if (world && GameEvents) {
            Shop1Log("drag_update_send", {
                x: world[0],
                y: world[1],
                z: world[2]
            }, true, true);
            if (SHOP1_DRAG_DEBUG) {
                var now = Game.GetGameTime();
                if (now - shop1DragDebugLast > 0.5) {
                    shop1DragDebugLast = now;
                    $.Msg("[Shop1DragFx] UpdatePos", "x=", world[0], "y=", world[1], "z=", world[2]);
                }
            }
            GameEvents.SendCustomGameEventToServer("shop1_drag_fx_update", {
                x: world[0],
                y: world[1],
                z: world[2]
            });
        } else if (!world) {
            Shop1Log("drag_update_no_world", { cursor: cursor }, true, true);
        }
    } else {
        Shop1Log("drag_update_no_cursor", {}, true, true);
    }
    $.Schedule(0.03, UpdateShop1DragFx);
}

function OnUpdateQueryUnit()
{
    //$.Msg( "OnUpdateQueryUnit ", Players.GetQueryUnit(Players.GetLocalPlayer()));
