function ResolveShop1ClickPending() {
    shop1ClickPendingTimer = false;
    if (!shop1ClickPending) {
        return;
    }
    var cfg = GameUI.CustomUIConfig();
    if (!cfg) {
        return;
    }
    var pid = Players.GetLocalPlayer();
    var selected = Players.GetSelectedEntities(pid) || [];
    var selEnt = selected.length > 0 ? selected[0] : -1;
    var sameEnt = (selEnt !== -1 && selEnt === shop1ClickPendingEnt);
    if (!sameEnt && selEnt !== -1 && shop1ClickPendingProxy !== -1) {
        sameEnt = selEnt === shop1ClickPendingProxy;
    }
    if (!sameEnt && selEnt !== -1 && Entities && Entities.IsValidEntity) {
        if (IsShop1SelectionProxy(selEnt) && shop1ClickPendingProxy !== -1) {
            sameEnt = selEnt === shop1ClickPendingProxy;
        }
    }

    if (SHOP1_CLICK_DEBUG) {
        $.Msg("[Shop1ClickPending]",
            "sameEnt=", sameEnt,
            "sel=", selEnt,
            "pendingEnt=", shop1ClickPendingEnt,
            "pendingProxy=", shop1ClickPendingProxy);
    }

    if (sameEnt) {
        cfg.selection_force_close_pending = false;
        cfg.selection_force_close = true;
        cfg.selection_force_close_time = Game.GetGameTime();
    } else {
        cfg.selection_force_close_pending = false;
        cfg.selection_force_close = false;
    }
    shop1ClickPending = false;
}

(function () {
    // Custom event listeners
    GameEvents.Subscribe("selection_new", Selection_New);
    GameEvents.Subscribe("selection_add", Selection_Add);
    GameEvents.Subscribe("selection_remove", Selection_Remove);
    GameEvents.Subscribe("selection_reset", Selection_Reset);

    // Built-In Dota client events
    GameEvents.Subscribe("dota_player_update_selected_unit", OnUpdateSelectedUnit);
    GameEvents.Subscribe("dota_player_update_query_unit", OnUpdateQueryUnit);

    function UpdateShop1DummyRange(event) {
        var cfg = GameUI.CustomUIConfig();
        if (!cfg) {
            return;
        }

        var ent = event && event.entindex !== undefined ? event.entindex : -1;
        var proxyEnt = event && event.selection_proxy_entindex !== undefined ? event.selection_proxy_entindex : -1;
        var ability = event && event.ability ? event.ability : "";
        var range = event && event.projectile_range !== undefined ? Number(event.projectile_range) : 0;

        var heroIcon = event && event.hero_icon ? event.hero_icon : "";
        if (!ability || ent === -1) {
            cfg.shop1_dummy_ent = -1;
            cfg.shop1_dummy_proxy_ent = -1;
            cfg.shop1_dummy_range = 0;
            cfg.shop1_dummy_hero_icon = "";
            if (SHOP1_CLICK_DEBUG) {
                $.Msg("[Shop1Dummy] cleared", "ent=", ent, "pending=",
                    cfg.selection_force_close_pending ? "1" : "0");
            }
            if (cfg.selection_force_close_pending) {
                cfg.selection_force_close_pending = false;
                cfg.selection_force_close = true;
                cfg.selection_force_close_time = Game.GetGameTime();
            }
            shop1ClickPending = false;
            CancelShop1DragFx();
            return;
        }

        cfg.shop1_dummy_ent = ent;
        cfg.shop1_dummy_proxy_ent = proxyEnt;
        if (!isFinite(range) || range < 0) {
            range = 0;
        }
        cfg.shop1_dummy_range = range;
        cfg.shop1_dummy_hero_icon = heroIcon || "";
        if (heroIcon) {
            PreloadShop1Icon(heroIcon, "dummy_selection");
        } else {
            Shop1Log("dummy_selection_clear", { ent: ent, ability: ability }, true);
        }
        if (SHOP1_CLICK_DEBUG) {
            $.Msg("[Shop1Dummy] set",
                "ent=", ent,
                "proxy=", proxyEnt,
                "ability=", ability,
                "pending=", cfg.selection_force_close_pending ? "1" : "0");
        }
        if (cfg.selection_force_close_pending && shop1ClickPending) {
            var sameEnt = (ent === shop1ClickPendingEnt) || (proxyEnt !== -1 && proxyEnt === shop1ClickPendingProxy);
            if (sameEnt) {
                cfg.selection_force_close_pending = false;
                cfg.selection_force_close = true;
                cfg.selection_force_close_time = Game.GetGameTime();
                shop1ClickPending = false;
                return;
            }
        }
        if (cfg.selection_force_close_pending) {
            cfg.selection_force_close_pending = false;
            cfg.selection_force_close = false;
        }
        shop1ClickPending = false;
    }

    GameEvents.Subscribe("shop1_dummy_selection", UpdateShop1DummyRange);
    GameEvents.Subscribe("shop1_dummy_refresh", UpdateShop1DummyRange);
})();

// Shop1 mouse handling (moved from init.js)
(function () {
    var shop1MouseCallbackReady = false;
    var lastCameraWheelTime = 0;
    var cameraWheelCooldown = 0.03;

    function HandleLeftRelease() {
        if (!shop1LeftDown) {
            return;
        }
        shop1ReleasePending = true;
        shop1LeftDown = false;
        shop1SwallowPressed = false;
        Shop1Log("left_release_mouse", { dragActive: shop1DragFx.active }, true);
        SendLeftRelease();
        StopShop1DragFx();
        $.Schedule(0.2, function () {
            shop1ReleasePending = false;
        });
    }

    function SendCameraWheel(delta) {
        if (!delta || delta === 0) {
            return false;
        }
        var now = Game.GetGameTime();
        if (now - lastCameraWheelTime < cameraWheelCooldown) {
            return true;
        }
        lastCameraWheelTime = now;
        GameEvents.SendCustomGameEventToServer("camera_zoom_override", { delta: delta });
        return true;
    }

    function RegisterShop1MouseCallback(force) {
        if (shop1MouseCallbackReady && !force) {
            return;
        }
        if (!GameUI || !GameUI.SetMouseCallback) {
            Shop1Log("mouse_callback_missing", {}, true);
            return;
        }

        GameUI.SetMouseCallback(function (eventName, arg) {
            var swallowSelection = shop1DragFx.active === true || shop1SwallowPressed === true;
            if (eventName === "released") {
                if (arg !== "MOUSE_LEFT" && arg !== 0) {
                    return false;
                }
                if (SHOP1_RELEASE_DEBUG) {
                    var cur = GameUI.GetCursorPosition();
                    var sel = Players.GetSelectedEntities(Players.GetLocalPlayer()) || [];
                    var sel0 = sel.length > 0 ? sel[0] : -1;
                    // $.Msg("[Shop1Release] released",
                    //     "cursor=", cur ? (cur[0] + "," + cur[1]) : "nil",
                    //     "selected=", sel0,
                    //     "leftDown=", shop1LeftDown,
                    //     "dragActive=", shop1DragFx.active);
                    if (cur && cur.length >= 2 && GameUI.FindScreenEntities) {
