function Shop1Log(tag, data, toServer, throttle) {
    if (!SHOP1_LOG) {
        return;
    }
    var now = Game.GetGameTime();
    if (throttle && now - shop1LogLastUpdate < SHOP1_LOG_UPDATE_INTERVAL) {
        return;
    }
    if (throttle) {
        shop1LogLastUpdate = now;
    }
    shop1LogSeq += 1;
    var payload = data || {};
    payload.t = now;
    payload.seq = shop1LogSeq;
    $.Msg("[Shop1Log]", tag, JSON.stringify(payload));
    if (toServer && GameEvents) {
        GameEvents.SendCustomGameEventToServer("shop1_drag_debug", {
            tag: tag,
            t: now,
            seq: shop1LogSeq,
            data: JSON.stringify(payload)
        });
    }
}

function Shop1InputDebug(tag, data) {
    if (!SHOP1_INPUT_DEBUG) {
        return;
    }
    var payload = data || {};
    payload.t = Game.GetGameTime();
    $.Msg("[Shop1Input]", tag, JSON.stringify(payload));
}

function EnsureShop1PreloadContainer() {
    if (shop1PreloadContainer) {
        return shop1PreloadContainer;
    }
    var parent = GetHudPanelSafe();
    if (!parent) {
        return null;
    }
    shop1PreloadContainer = $.CreatePanel("Panel", parent, "Shop1IconPreloadLayer");
    shop1PreloadContainer.style.width = "0px";
    shop1PreloadContainer.style.height = "0px";
    shop1PreloadContainer.style.visibility = "collapse";
    shop1PreloadContainer.hittest = false;
    return shop1PreloadContainer;
}

function PreloadShop1Icon(iconPath, reason) {
    if (!iconPath) {
        return;
    }
    var icon = iconPath;
    if (typeof NormalizePanoramaImagePath === "function") {
        icon = NormalizePanoramaImagePath(iconPath);
    }
    if (!icon || shop1IconCache[icon]) {
        return;
    }
    var container = EnsureShop1PreloadContainer();
    if (!container) {
        return;
    }
    var img = $.CreatePanel("Image", container, "Shop1IconPreload_" + Object.keys(shop1IconCache).length);
    img.style.visibility = "collapse";
    img.hittest = false;
    img.SetImage(icon);
    shop1IconCache[icon] = true;
    Shop1Log("icon_preload", { icon: icon, reason: reason || "" }, true);
}

// Recieves a list of entities to replace the current selection
function Selection_New(msg)
{
    var entities = msg.entities
    //$.Msg("Selection_New ", entities)
    for (var i in entities) {
        if (i==1)
            GameUI.SelectUnit(entities[i], false) //New
        else
            GameUI.SelectUnit(entities[i], true) //Add
    };
    $.Schedule(0.03, SendSelectedEntities);
}

